//! Sivm policy body and validation methods. Accessor
//! `MeasuredProductPolicy::sivm` is generated by `define_product_policy!`
//! in `lib.rs`.

extern crate alloc;

use alloc::vec::Vec;

use crate::uefi_security_policy::UefiSecurityPolicy;

/// Sivm policy body.
#[derive(mesh_protobuf::Protobuf, Debug, Clone, PartialEq, Default)]
#[cfg_attr(feature = "manifest", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(
    feature = "manifest",
    serde(rename_all = "snake_case", deny_unknown_fields)
)]
#[cfg_attr(feature = "inspect", derive(inspect::Inspect))]
#[mesh(package = "openhcl.product_policy")]
pub struct SivmPolicy {
    /// Reserved: require an ephemeral VMGS. Not enforced at runtime yet.
    #[mesh(1)]
    pub require_ephemeral_vmgs: bool,

    /// Require secure boot is enabled.
    #[mesh(2)]
    pub require_secure_boot: bool,

    /// Reserved: require PK/KEK/db/dbx variables. Not enforced at runtime yet.
    #[mesh(3)]
    pub require_secure_boot_vars: bool,

    /// Reserved: require `BootConfigurationDataHash`. Not enforced at runtime yet.
    #[mesh(4)]
    pub require_bcd_integrity: bool,

    /// Custom UEFI JSON bytes (base64 in manifest JSON). Required in
    /// manifests and asserted non-empty at build time when secure boot
    /// plus secure-boot-vars or BCD-integrity are set;
    #[mesh(5)]
    #[cfg_attr(
        feature = "manifest",
        serde(with = "super::product_policy_helpers::custom_uefi_json_serde")
    )]
    #[cfg_attr(feature = "inspect", inspect(with = "Vec::<u8>::len"))]
    pub custom_uefi_json: Vec<u8>,

    /// PCI devices that the VPCI relay may expose to VTL0, in addition to the
    /// devices OpenHCL always allows. Optional in manifests; an empty list is
    /// not encoded, so existing policies keep their measurement.
    #[mesh(6)]
    #[cfg_attr(feature = "manifest", serde(default))]
    #[cfg_attr(feature = "inspect", inspect(iter_by_index))]
    pub allowed_pci_devices: Vec<AllowedPciDevice>,
}

/// A PCI device that a [`SivmPolicy`] allows the VPCI relay to expose to VTL0.
/// Unset IDs match any value. Manifest JSON has no hex literals, so IDs are
/// decimal, e.g. `{ "vendor_id": 4318, "device_id": 9988 }` for `10de:2704`.
#[derive(mesh_protobuf::Protobuf, Debug, Clone, PartialEq)]
#[cfg_attr(feature = "manifest", derive(serde::Serialize, serde::Deserialize))]
#[cfg_attr(
    feature = "manifest",
    serde(rename_all = "snake_case", deny_unknown_fields)
)]
#[cfg_attr(feature = "inspect", derive(inspect::Inspect))]
#[mesh(package = "openhcl.product_policy")]
pub struct AllowedPciDevice {
    /// Vendor ID. Required, so an entry can never match every device.
    #[mesh(1)]
    #[cfg_attr(feature = "inspect", inspect(hex))]
    pub vendor_id: u16,
    /// Device ID.
    #[mesh(2)]
    #[cfg_attr(feature = "inspect", inspect(hex))]
    pub device_id: Option<u16>,
    /// Revision ID.
    #[mesh(3)]
    #[cfg_attr(feature = "inspect", inspect(hex))]
    pub revision_id: Option<u8>,
}

impl crate::uefi_security_policy::UefiSecurityPolicyParams for SivmPolicy {
    fn require_secure_boot(&self) -> bool {
        self.require_secure_boot
    }
}

impl UefiSecurityPolicy for SivmPolicy {}
